#include <iostream>
#include <vector>
#include <cassert>

using namespace std;

#define FOR(i, a, b) for (int i = (a); i < (b); ++i)
#define REP(i, n) FOR(i, 0, n)

typedef long long ll;

const int MOD = 1e9 + 7;

int sum_mod(int a, int b) {
    int s = a + b;
    if (s >= MOD) s -= MOD;
    return s;
}

int product_mod(int a, int b) {
    return (ll)a * b % MOD;
}

const int DIMENSION = 32;

struct Matrix {
    int mat[DIMENSION][DIMENSION];
    Matrix() { for (int i = 0; i < DIMENSION; ++i) for (int j = 0; j < DIMENSION; ++j) mat[i][j] = 0; }
    int* operator[](int i) { return mat[i]; }
    friend Matrix operator*(const Matrix& A, const Matrix& B) {
        Matrix R;
        for (int i = 0; i < DIMENSION; ++i)
            for (int j = 0; j < DIMENSION; ++j)
                for (int k = 0; k < DIMENSION; ++k)
                    R[i][j] = sum_mod(R[i][j], product_mod(A[i][k], B[k][j]));
        return R;
    }
};

const int MAX_D = 64;
const int MAX_K = 32;

Matrix f[MAX_D];
int k;

Matrix build_matrix(int n, int offset) {
    Matrix M;
    for (int i = 0; i <= k; ++i)
        for (int j = 0; j <= k; ++j) {
            int ni = (i == k) ? i : (i + offset) % k;
            int nj = (j == k) ? j : (j + offset) % k;
            M[ni][nj] = f[n][i][j];
        }
    return M;
}

int digit_sum(ll n) {
    int sum = 0;
    while (n > 0) {
        sum += n % k;
        n /= k;
    }
    return sum % k;
}

int main() {
    ll n;
    int base;
    cin >> n >> base;
    k = base;

    int digits_count = 0;
    ll temp = n;
    while (temp > 0) {
        temp /= k;
        ++digits_count;
    }

    Matrix identity;
    for (int i = 0; i <= k; ++i) identity[i][i] = 1;

    f[0] = identity;
    for (int i = 0; i <= k; ++i) f[0][i][0] = 1;

    for (int i = 1; i < digits_count; ++i) {
        f[i] = identity;
        for (int j = 0; j < k; ++j)
            f[i] = f[i] * build_matrix(i - 1, j);
    }

    ll current = 0;
    ll power = 1;

    --digits_count;
    for (int i = 0; i < digits_count; ++i) power *= k;

    Matrix result = identity;
    while (current < n) {
        assert(digits_count >= 0);
        while (current + power <= n) {
            result = result * build_matrix(digits_count, digit_sum(current));
            current += power;
        }
        power /= k;
        --digits_count;
    }

    int total = 0;
    for (int i = 0; i <= k; ++i)
        total = sum_mod(total, result[k][i]);
    cout << total << "\n";
    return 0;
}
